package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.NoClass;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.jsontype.*;
import com.fasterxml.jackson.databind.jsontype.JsonTypeInfo;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

public class StdTypeResolverBuilder_typeProperty_TriageGen1Test {

    @Test
    public void testTypeProperty_WithValidString() {
        // Arrange
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder();
        String expectedProp = "myCustomProperty";

        // Act
        StdTypeResolverBuilder result = builder.typeProperty(expectedProp);

        // Assert
        assertEquals("The builder should return itself (fluent API)", builder, result);
        assertEquals("The type property should match the input string", expectedProp, builder.getTypeProperty());
    }

    @Test
    public void testTypeProperty_WithNull() {
        // Arrange
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder();
        JsonTypeInfo.Id mockId = Mockito.mock(JsonTypeInfo.Id.class);
        String defaultProp = "defaultId";

        // We need to initialize the builder with an idType so getDefaultPropertyName() can be called
        // Since _idType is private, we use init() as provided in the signature
        builder.init(Mockito.mock(JsonTypeInfo.Id.class), Mockito.mock(TypeIdResolver.class));

        // To control the behavior of _idType.getDefaultPropertyName(), 
        // we'd ideally need to inject it, but since we are testing the logic:
        // We simulate the internal state via the init method if possible, 
        // or rely on the fact that we can't easily mock the internal _idType without reflection.
        // However, based on the provided signature, we use the provided methods.

        // Note: In a real Jackson environment, the IdType is set during init.
        // Let's use reflection to set the internal field to ensure we test the branch coverage perfectly.
        try {
            java.lang.reflect.Field idTypeField = StdTypeResolverBuilder.class.getDeclaredField("_idType");
            idTypeField.setAccessible(true);
            JsonTypeInfo.Id mockIdType = Mockito.mock(JsonTypeInfo.Id.class);
            when(mockIdType.getDefaultPropertyName()).thenReturn(defaultProp);
            idTypeField.set(builder, mockIdType);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Act
        builder.typeProperty(null);

        // Assert
        assertEquals("When null is passed, it should revert to the default property name", defaultProp, builder.getTypeProperty());
    }

    @Test
    public void testTypeProperty_WithEmptyString() {
        // Arrange
        StdTypeResolverBuilder builder = new StdTypeResolverBuilder();
        String defaultProp = "defaultId";

        try {
            java.lang.reflect.Field idTypeField = StdTypeResolverBuilder.class.getDeclaredField("_idType");
            idTypeField.setAccessible(true);
            JsonTypeInfo.Id mockIdType = Mockito.mock(JsonTypeInfo.Id.class);
            when(mockIdType.getDefaultPropertyName()).thenReturn(defaultProp);
            idTypeField.set(builder, mockIdType);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Act
        builder.typeProperty("");

        // Assert
        assertEquals("When empty string is passed, it should revert to the default property name", defaultProp, builder.getTypeProperty());
    }
}
